text:
This project concerns private health data. Repository access and FASRC storage controls are necessary but do not decide what may enter a release.
Before source inspection or curation begins, a human data steward must record:

the authoritative source location and custodian;
whether files contain direct or quasi-identifiers;
approved users and computational locations;
permissible row- and geography-level release grain;
masking, aggregation, and small-cell rules;
retention and deletion requirements;
the reviewer who authorizes publication.

These are scientific and governance decisions, not infrastructure defaults. Until they are recorded, Pipeline pages deliberately stop at inventory and scaffolding. Do not include values, screenshots, tables, or summaries derived from protected data in the rendered Manual.

Before DHIS2, there was GESIS.
This page builds the clinic-month identity crosswalk from the legacy monthly inventory of conditions; the cleaned DHIS2–GESIS mapping; and the reviewed GESIS corrections. The reviewed rules below remain explicit so their effects can be checked before the resulting IDs are used downstream.






Important Prerequisite: Make The Legacy Monthly Inventory Available



This stage begins by reading in a set of raw data “from Kevin” that is used to define “unique clinic months”.
The cleaned mapping is the s1_gesis_xwalk_clean_df target from the preceding page.








Tip Procedure: Declare Identity And Input Helpers



targets tracks the source archive and the rebuilt Parquet inventory as files, while the mapping dependency uses the preceding page’s in-memory data target. The selectors resolve reviewed inputs from the staged-input inventory rather than relying on the old script’s working directory.
The combined inventory reuses s0_pipeline_parquet_transform_fn from page 18. It reads with prudence = "stingy", writes the ordered relation, and returns the tracked output path.
library(targets)
library(dplyr)
library(readr)
library(readxl)
library(stringr)
library(stringi)
library(duckplyr)

s2_clinic_ids_mode_fn &lt;- function(x, na.rm = FALSE) {
  if (na.rm) x &lt;- x[!is.na(x)]
  values &lt;- unique(x)
  values[which.max(tabulate(match(x, values)))]
}

s2_clinic_ids_first_fn &lt;- function(x) {
  if (length(x) == 0L) NA else dplyr::first(x)
}
Require one staged match for each reviewed input, so an ambiguous selection fails before the corresponding data is read.
s2_pipeline_input_select_single_fn &lt;- function(paths, pattern) {
  matches &lt;- stringr::str_subset(paths, pattern)
  if (length(matches) != 1L) {
    stop("Expected one staged input matching /", pattern, "/; found ", length(matches), ".")
  }
  matches
}








Tip Procedure: Select Monthly Archive Members



The archived legacy script selects the six identity columns and removes duplicates within each monthly CSV before combining files. Keeping the health measurement columns would repeat every identity for each reported measurement. We perform that reduction in DuckDB and write one Parquet artifact per member.
Only YYYY_MM.csv members in mdg_tall_split/ are selected. This reproduces the legacy numeric-filename selection for this freeze and excludes missing_date.csv, diar_pneu_fix.csv, AVC.csv, and macOS metadata. Sorting the members reproduces the legacy list.files() order.
The 120 monthly CSVs in the May 2025 freeze use Windows-1252. A complete byte scan found 9C, A8, E0, E8, E9, EB, and F4 outside ASCII. For example, Ampitafà contains byte E0, and Sœurs contains 9C; the latter distinguishes Windows-1252 from ISO-8859-1 (Latin-1). A UTF-8 process locale does not change these file bytes, and Latin-1 is not a valid substitute for this archive.
Use DuckDB’s official encodings extension with encoding = "CP1252". INSTALL reuses the installed extension after the first download; a new runtime or DuckDB version needs network access for that download. LOAD runs on duckplyr’s own connection in each worker. Decoding happens in DuckDB before reduction, leaving UTF-8 names in Parquet without loading the tall CSV into R or skipping invalid rows. The staged archive stays unchanged.
s2_clinic_months_identity_columns_fn &lt;- function() {
  c("cNom", "cAnnee", "cPeriode", "cCodeNiv", "cCodeStru", "fname")
}

s2_clinic_months_list_members_fn &lt;- function(archive_path) {
  members &lt;- utils::unzip(archive_path, list = TRUE)$Name
  members &lt;- members[
    grepl("(^|/)mdg_tall_split/[0-9]{4}_[0-9]{2}\\.csv$", members) &
      !grepl("(^|/)__MACOSX/", members)
  ]
  stopifnot(length(members) &gt; 0L, !anyDuplicated(basename(members)))
  sort(members, method = "radix")
}








Tip Procedure: Decode And Reduce One Monthly CSV



Extract a member into a private temporary directory, decode its identity fields, and keep the first occurrence of each identity. Only the reduced Parquet path leaves the branch. The temporary CSV is removed on exit.
s2_clinic_months_reduce_csv_fn &lt;- function(csv_path, source_file) {
  # Read text first: read.csv() keeps empty clinic names but treats NA as missing.
  # Cast only the five numeric identity fields, matching the archived integers.
  column_types &lt;- c(
    cNom = "VARCHAR", cAnnee = "VARCHAR", cPeriode = "VARCHAR",
    cCodeNiv = "VARCHAR", cCodeStru = "VARCHAR", cCode = "VARCHAR",
    fname = "VARCHAR", Variable = "VARCHAR", Value = "VARCHAR"
  )
  identity_columns &lt;- s2_clinic_months_identity_columns_fn()
  integer_columns &lt;- setdiff(identity_columns, "cNom")
  duckplyr::db_exec("INSTALL encodings")
  duckplyr::db_exec("LOAD encodings")
  result &lt;- read_csv_duckdb(
    csv_path,
    prudence = "stingy",
    options = list(
      header = TRUE, delim = ",", quote = "\"", escape = "\"",
      types = list(column_types), nullstr = "NA", encoding = "CP1252"
    )
  ) |&gt;
    select(all_of(identity_columns)) |&gt;
    mutate(
      across(
        all_of(integer_columns),
        ~ as.integer(if_else(.x == "", NA_character_, .x))
      ),
      .inventory_row = row_number()
    ) |&gt;
    summarise(.inventory_row = min(.inventory_row), .by = all_of(identity_columns)) |&gt;
    mutate(.inventory_file = source_file) |&gt;
    arrange(.inventory_row)

  result
}
The branch writer owns extraction and cleanup. It passes the extracted CSV to the reducer and returns the completed Parquet path.
s2_clinic_months_write_member_fn &lt;- function(archive_path, member, output_path) {
  stopifnot(
    length(archive_path) == 1L, file.exists(archive_path),
    length(member) == 1L,
    !grepl("^/|(^|/)\\.\\.(/|$)", member)
  )

  extraction_dir &lt;- tempfile("clinic-month-")
  dir.create(extraction_dir)
  on.exit(unlink(extraction_dir, recursive = TRUE), add = TRUE)
  csv_path &lt;- utils::unzip(archive_path, files = member, exdir = extraction_dir)
  stopifnot(length(csv_path) == 1L, file.exists(csv_path))

  result &lt;- s2_clinic_months_reduce_csv_fn(csv_path, basename(member))

  dir.create(dirname(output_path), recursive = TRUE, showWarnings = FALSE)
  compute_parquet(result, output_path)
  output_path
}








Tip Procedure: Build The Ordered Monthly Inventory



Select the source archive and its monthly members for dynamic branching.
#| format: file
s2_clinic_months_raw_zip &lt;- s2_pipeline_input_select_single_fn(
  s0_pipeline_inputs_raw_chr,
  "(^|/)madagascar_clinic_data_cleaning\\.zip$"
)
s2_clinic_months_members_chr &lt;- s2_clinic_months_list_members_fn(
  s2_clinic_months_raw_zip
)
The execution page declares a dynamic branch per archive member, producing s2_clinic_months_deduplicated_parquet. Each branch extracts into its own temporary directory and deletes the CSV after the Parquet write finishes. prudence = "stingy" prevents accidental fallback that would materialize raw data in R. Only artifact paths cross the targets boundary.
The combined inventory deliberately retains repeats across files, matching the legacy procedure. .inventory_file and .inventory_row record file order and the first source-row position for each identity. They preserve first-occurrence tie breaking in the downstream mode calculations; SQL grouping alone does not guarantee that order.
#| format: file
s2_clinic_months_inventory_parquet &lt;- s0_pipeline_parquet_transform_fn(
  input_paths = s2_clinic_months_deduplicated_parquet,
  output_path = here::here("data", "intermediates", "unique_clinic_months_v1-2.parquet"),
  transform = function(relation) {
    relation |&gt; arrange(.inventory_file, .inventory_row)
  }
)








Tip Procedure: Select Reviewed Identity Inputs



The correction workbook, reviewed deletions, and verified snips are selected here for the identity transformations below:
#| format: file
s2_gesis_code_corrections_raw_xlsx &lt;- s2_pipeline_input_select_single_fn(
  s0_pipeline_inputs_raw_chr,
  "CSB1 CSB2 PUBLIC PRIVATE\\.xlsx$"
)
#| format: file
s2_gesis_code_deletions_raw_csv &lt;- s2_pipeline_input_select_single_fn(
  s0_pipeline_inputs_raw_chr,
  "VERIFIER clinic_codes_in_gesis_but_not_in_mapping\\.csv$"
)

s2_gesis_snips_verified_csv &lt;- s2_pipeline_input_select_single_fn(
  s0_pipeline_inputs_raw_chr,
  "GESIS_snips_public_multipleLongGESIS VERIFIED\\.csv$"
)








Tip Procedure: Collect The Reduced Identity Inventory



Collect only the six identity fields, in original file and row order. This order determines the first occurrence when the modal identity has a tie. The tall measurement tables remain in DuckDB and Parquet.
s2_clinic_months_inventory_df &lt;- read_parquet_duckdb(
  s2_clinic_months_inventory_parquet, prudence = "stingy"
) |&gt;
  arrange(.inventory_file, .inventory_row) |&gt;
  select(all_of(s2_clinic_months_identity_columns_fn())) |&gt;
  collect() |&gt;
  mutate(across(!c(cAnnee, cPeriode, fname), as.character))








Tip Procedure: Read And Apply Reviewed Code Corrections



Read the correction workbook as character codes, then retain the original code wherever no replacement was reviewed. Assign the mapping year here: January–March 2015 and records with fname == 1 use the old mapping; later 2015 records use the new mapping.
s2_gesis_code_corrections_df &lt;- readxl::read_excel(s2_gesis_code_corrections_raw_xlsx) |&gt;
  filter(!is.na(`NEW CODE`), `NEW CODE` != "NEW CODE") |&gt;
  setNames(c("old_code", "correct_code", "uid", "name", "status", "note")) |&gt;
  unique()
The corrected inventory carries the selected mapping year into the next join.
s2_clinic_months_corrected_df &lt;- s2_clinic_months_inventory_df |&gt;
  left_join(
    s2_gesis_code_corrections_df |&gt; select(cCodeStru = old_code, correct_cCodeStru = correct_code)
  ) |&gt;
  mutate(correct_cCodeStru = coalesce(correct_cCodeStru, cCodeStru)) |&gt;
  mutate(
    map_year = case_when(
      cAnnee == 2015 & cPeriode &lt;= 3 ~ "OLD GESIS 2015",
      cAnnee == 2015 & fname == 1 ~ "OLD GESIS 2015",
      cAnnee == 2015 & cPeriode &gt; 3 ~ "NEW GESIS 2015",
      TRUE ~ as.character(cAnnee)
    )
  )








Tip Procedure: Join The Year-Aware Facility Mapping



Prepare the identity mapping with its three reviewed exceptions: exclude the 2012–2013 UID match and the invalid old-2015 code, then clear the disputed 2014 UID. Join this mapping on corrected GESIS code and mapping year.
s2_gesis_xwalk_identity_df &lt;- s1_gesis_xwalk_clean_df |&gt;
  filter(!(fs_uid == "gIAGmHMV9MS" & cAnnee %in% c("2013", "2012"))) |&gt;
  filter(!(code_fs == "630242008" & cAnnee == "OLD GESIS 2015")) |&gt;
  mutate(fs_uid = ifelse(code_fs == 110543027 & cAnnee == "2014", "", fs_uid)) |&gt;
  transmute(
    map_year = cAnnee,
    correct_cCodeStru = as.character(code_fs),
    TYPE,
    fs_uid,
    map_name = FS
  )
Keep unmatched identities for the UID-fill and name-fallback stages.
s2_clinic_months_gesis_mapped_df &lt;- s2_clinic_months_corrected_df |&gt;
  left_join(
    s2_gesis_xwalk_identity_df,
    by = c("correct_cCodeStru", "map_year")
  )








Tip Procedure: Fill Unambiguous UIDs And Mapping Attributes



Within each corrected-code/name group, fill the UID only when the nonmissing values identify one candidate. Then fill missing type and mapped name from their modes within the UID/code/name group. Retain the existing tie behavior.
s2_clinic_month_uid_filled_df &lt;- s2_clinic_months_gesis_mapped_df |&gt;
  mutate(
    group_uid = {
      values &lt;- unique(na.omit(fs_uid))
      case_when(
        length(values) == 1L ~ s2_clinic_ids_first_fn(values),
        length(values) == 2L & any(values == "") ~ s2_clinic_ids_first_fn(setdiff(values, ""))
      )
    },
    .by = c(correct_cCodeStru, cNom)
  ) |&gt;
  mutate(
    fs_uid = ifelse(is.na(fs_uid) | fs_uid == "", group_uid, fs_uid)
  ) |&gt;
  group_by(fs_uid, correct_cCodeStru, cNom) |&gt;
  mutate(across(c(TYPE, map_name), list(uid = ~ {
    mode &lt;- s2_clinic_ids_mode_fn(.x, na.rm = TRUE)
    if (dplyr::n_distinct(mode) == 1L) mode else NA
  }))) |&gt;
  ungroup() |&gt;
  mutate(TYPE = coalesce(TYPE, TYPE_uid), map_name = coalesce(map_name, map_name_uid)) |&gt;
  select(-TYPE_uid, -map_name_uid, -group_uid)








Tip Procedure: Assign Provisional IDs And Apply Reviewed Deletions



Use the mapped name when present; otherwise normalize the already-decoded UTF-8 clinic name to ASCII. Prefer a DHIS2 UID and fall back to corrected code plus cleaned name when the UID is missing.
s2_clinic_month_provisional_ids_df &lt;- s2_clinic_month_uid_filled_df |&gt;
  mutate(
    clean_name = ifelse(
      is.na(map_name),
      cNom |&gt;
        stringi::stri_trans_general(id = "Latin-ASCII") |&gt;
        str_trim() |&gt;
        str_squish() |&gt;
        stringr::str_remove("^CSB2|^CSB1|^CSB|CBS") |&gt;
        tolower(),
      map_name
    ),
    clinic_ID = ifelse(
      is.na(fs_uid) | fs_uid == "",
      paste0(correct_cCodeStru, " - ", clean_name),
      fs_uid
    )
  )
Read the reviewed deletion codes and clear the designated IDs without dropping their rows. The code/year exception for 610351004 is retained.
s2_clinic_gesis_deletion_codes_chr &lt;- read_csv(s2_gesis_code_deletions_raw_csv, show_col_types = FALSE) |&gt;
  filter(NOTE == "DELETE") |&gt;
  pull(clinic_code) |&gt;
  as.character()
s2_clinic_ids_corrected_df &lt;- s2_clinic_month_provisional_ids_df |&gt;
  mutate(
    clinic_ID = case_when(
      correct_cCodeStru == "610351004" & cAnnee == 2016 ~ NA_character_,
      correct_cCodeStru %in% s2_clinic_gesis_deletion_codes_chr ~ NA_character_,
      TRUE ~ clinic_ID
    )
  )








Tip Procedure: Reconcile Verified GESIS Snips



Read the reviewed shortened GESIS codes. Exclude the four ambiguous snips before joining, then use the modal UID or clinic ID only for verified groups with more than one identity.
s2_clinic_verified_snips_df &lt;- read_delim(s2_gesis_snips_verified_csv, delim=",", show_col_types = FALSE) |&gt;
  filter(!is.na(GESIS_short)) |&gt;
  mutate(GESIS_short = as.character(GESIS_short)) |&gt;
  transmute(
    GESIS_snip = GESIS_short,
    verified_snip = `VERIFIED (1 CORRECT – 0 INCORRECT)`
  )
The first reconciliation leaves the commune/name rules for the next step.
s2_clinic_ids_snip_reconciled_df &lt;- s2_clinic_ids_corrected_df |&gt;
  mutate(
    GESIS_snip = paste0(str_sub(correct_cCodeStru, 1, 4), str_sub(correct_cCodeStru, 7, 9))
  ) |&gt;
  left_join(
    s2_clinic_verified_snips_df |&gt;
      filter(!GESIS_snip %in% c("1104006", "1104060", "5205039", "5202030")) |&gt;
      filter(verified_snip == "1"),
    by = "GESIS_snip"
  ) |&gt;
  group_by(GESIS_snip) |&gt;
  mutate(
    clinic_ID = case_when(
      n_distinct(clinic_ID) &gt; 1 & any(fs_uid != "") & verified_snip == "1" ~
        s2_clinic_ids_first_fn(s2_clinic_ids_mode_fn(setdiff(fs_uid, ""), na.rm = TRUE)),
      n_distinct(clinic_ID) &gt; 1 & verified_snip == "1" ~
        s2_clinic_ids_first_fn(s2_clinic_ids_mode_fn(clinic_ID, na.rm = TRUE)),
      TRUE ~ clinic_ID
    )
  ) |&gt;
  ungroup()








Tip Procedure: Reconcile Commune And Clinic Names



Combine the commune code with the cleaned clinic name and reconcile the remaining multiple IDs within that group. Preserve the reviewed 2014 exception for GESIS code 110543027.
s2_clinic_ids_reconciled_df &lt;- s2_clinic_ids_snip_reconciled_df |&gt;
  mutate(
    commune_name = paste0(cCodeNiv, " - ", gsub("^CSB1 |^CSB2 |^CSB ", "", clean_name))
  ) |&gt;
  group_by(commune_name) |&gt;
  mutate(
    clinic_ID = case_when(
      correct_cCodeStru == "110543027" & cAnnee == 2014 ~ clinic_ID,
      n_distinct(clinic_ID) &gt; 1 & any(fs_uid != "") ~
        s2_clinic_ids_first_fn(s2_clinic_ids_mode_fn(setdiff(fs_uid, ""), na.rm = TRUE)),
      n_distinct(clinic_ID) &gt; 1 ~ s2_clinic_ids_first_fn(s2_clinic_ids_mode_fn(clinic_ID, na.rm = TRUE)),
      TRUE ~ clinic_ID
    )
  ) |&gt;
  ungroup()








Tip Procedure: Write The Clinic ID Crosswalk



The final crosswalk keeps the legacy columns and ID_checked indicator. Rows without a clinic ID are retained in the intermediate artifact for review; the 31 expected removals are not silently dropped here.
s2_clinic_ids_df &lt;- s2_clinic_ids_reconciled_df |&gt;
  group_by(clinic_ID) |&gt;
  mutate(ID_checked = any(grepl("CSB", TYPE))) |&gt;
  ungroup() |&gt;
  select(
    clinic_ID, cAnnee, cPeriode, cCodeNiv, cCodeStru,
    correct_cCodeStru, cNom, fname,
    type_map = TYPE, ID_checked
  )
#| format: file
s2_clinic_ids_parquet &lt;- {
  path &lt;- here::here("data", "intermediates", "w2010_2019_clinicID.parquet")
  dir.create(dirname(path), recursive = TRUE, showWarnings = FALSE)
  compute_parquet(as_duckdb_tibble(s2_clinic_ids_df), path)
  path
}
Downstream transformations can consume s2_clinic_ids_df directly. The Parquet copy is tracked with format = "file" for disk-based consumers and inspection. It preserves the crosswalk columns and missing values without adding a CSV row-index column. The legacy RDS and CSV exports are replaced by this single Parquet artifact.








Warning Check: Compare Most Recent Archived Data And Target Clinic Identities



Review note (2026-11-08). The researcher reports that the initial shape checks on pages 18–21 appear to pass. This records the initial clinic-identity shape review. This is a researcher-reported observation from the interactive review, not an independently rerun acceptance test. It does not establish key-level equality, measurement-value parity, or unchanged diagnosis definitions/IDs. Retain any remaining discrepancies for review.
Run these chunks in order from the repository root after the targets build. These are exploratory summaries; interpretation is left to the reader. Most recent archived data baseline records the selected iterations, evidence, and provenance limits. The shared selection is versioned in src/archived-comparison-baseline.R.
Use the May 1, 2025 script-2 intermediate RDS: the most recent archived data found for this stage. The different RDS under data/clean/ is dated October 2024. Only the selected member is extracted to the session temporary directory.
Load the pair for this page. Braces keep these session assignments out of tar_tangle(); the objects remain available for interactive exploration.
{
  archived_baseline &lt;- dget(here::here("src", "archived-comparison-baseline.R"))
  legacy_zip &lt;- here::here(archived_baseline$archive_zip)
  legacy_path &lt;- utils::unzip(
    legacy_zip, files = archived_baseline$clinic_ids_member,
    exdir = tempdir()
  )
  old_ids &lt;- readRDS(legacy_path)
  new_ids &lt;- targets::tar_read(s2_clinic_ids_df)
}
Rows and columns.
tibble::tibble(
  source = c("most recent archived data", "current pipeline"),
  rows = c(nrow(old_ids), nrow(new_ids)),
  columns = c(ncol(old_ids), ncol(new_ids))
)
Column names and order.
dplyr::bind_rows(
  `most recent archived data` = tibble::tibble(position = seq_len(ncol(old_ids)), column = names(old_ids)),
  `current pipeline` = tibble::tibble(position = seq_len(ncol(new_ids)), column = names(new_ids)),
  .id = "source"
)
Clinic-ID coverage by year.
dplyr::bind_rows(
  `most recent archived data` = old_ids |&gt; dplyr::summarise(
    rows = dplyr::n(), clinics = dplyr::n_distinct(clinic_ID, na.rm = TRUE),
    missing_ids = sum(is.na(clinic_ID)), .by = cAnnee
  ),
  `current pipeline` = new_ids |&gt; dplyr::summarise(
    rows = dplyr::n(), clinics = dplyr::n_distinct(clinic_ID, na.rm = TRUE),
    missing_ids = sum(is.na(clinic_ID)), .by = cAnnee
  ),
  .id = "source"
)

This page implements the pinned legacy 4A_clean_clinic_diagnosis.R at commit 31e0769683e133e136b09ac0c6608c5a12657a9a. Scientific rules and ambiguous edge cases retain legacy behavior. Measurement tables remain in DuckDB and tracked Parquet files; only rules, schemas, and aggregate audits enter R. The execution page owns dynamic branches. No nested futures or Slurm setup is introduced here.






Important Prerequisite: Require The Identity And Dictionary Products



Require pages 18–21: the prepared W3 Parquet, clinic-ID Parquet, monthly source archive/selectors, and diagnosis dictionary with its recorded W3 schema. S4 validates those dictionary rules as a dependency before interpreting them. This page stays unevaluated during rendering.








Tip Procedure: Declare Disk And SQL Helpers



SQL uses quoted identifiers and literals, never unrestricted R evaluation. DuckDB owns joins, reductions, and projection. Helpers return paths and clean up their temporary tables even after an error. CSV extraction remains private to the branch. CP1252 decoding reuses the official encodings extension.
s4a_diagnosis_literal_fn &lt;- function(x) {
  paste0("'", gsub("'", "''", x, fixed = TRUE), "'")
}
s4a_diagnosis_identifier_fn &lt;- function(x) {
  paste0('"', gsub('"', '""', x, fixed = TRUE), '"')
}
s4a_diagnosis_query_fn &lt;- function(sql) {
  duckplyr::read_sql_duckdb(sql, prudence = "stingy")
}
s4a_diagnosis_read_fn &lt;- function(paths) {
  stopifnot(length(paths) &gt; 0L, all(file.exists(paths)))
  paste0("read_parquet([", paste(s4a_diagnosis_literal_fn(paths), collapse = ","),
         "], union_by_name = true)")
}
s4a_diagnosis_write_fn &lt;- function(sql, path) {
  dir.create(dirname(path), recursive = TRUE, showWarnings = FALSE)
  duckplyr::compute_parquet(s4a_diagnosis_query_fn(sql), path)
  path
}
s4a_diagnosis_table_fn &lt;- function(name, sql) {
  duckplyr::db_exec(paste0("CREATE OR REPLACE TEMP TABLE ", name, " AS ", sql))
  name
}
s4a_diagnosis_cleanup_fn &lt;- function(names) {
  for (name in names) duckplyr::db_exec(paste("DROP TABLE IF EXISTS", name))
}
s4a_diagnosis_columns_fn &lt;- function(sql) {
  names(s4a_diagnosis_query_fn(paste0("SELECT * FROM (", sql, ") LIMIT 0")))
}
s4a_diagnosis_csv_fn &lt;- function(path, encoding = "CP1252") {
  if (encoding == "CP1252") {
    duckplyr::db_exec("INSTALL encodings")
    duckplyr::db_exec("LOAD encodings")
  }
  paste0("read_csv(", s4a_diagnosis_literal_fn(path),
         ", header=true, delim=',', quote='\"', escape='\"', nullstr='NA', ",
         "all_varchar=true, encoding=", s4a_diagnosis_literal_fn(encoding), ")")
}
s4a_diagnosis_tall_fn &lt;- function(sql, source) {
  paste0("SELECT cNom, CAST(nullif(cAnnee,'') AS INTEGER) cAnnee, ",
    "CAST(nullif(cPeriode,'') AS INTEGER) cPeriode, ",
    "CAST(CAST(nullif(cCodeNiv,'') AS BIGINT) AS VARCHAR) cCodeNiv, ",
    "CAST(CAST(nullif(cCodeStru,'') AS BIGINT) AS VARCHAR) cCodeStru, ",
    "CAST(nullif(fname,'') AS INTEGER) fname, cCode, Variable, ",
    "CAST(nullif(Value,'') AS DOUBLE) AS \"Value\", row_number() OVER () source_row, ",
    s4a_diagnosis_literal_fn(source), " source_file FROM ", sql)
}
s4a_diagnosis_drop_na_if_fn &lt;- function(x) {
  values &lt;- unique(stats::na.omit(x))
  if (length(values)) values else NA_integer_
}








Tip Procedure: Validate And Compile Dictionary Rules



The grammar is one exact source term or terms separated by +. Missing expressions produce numeric missing values. All harmonized measurements use a numeric Parquet schema, including columns R would infer as all-NA logical. Direct terms preserve sentinels; earlier-wave sums replace only -1, while W3 sums replace missing components. Repeated summands and unknown terms fail through the existing S3 validator.
s4a_diagnosis_rules_fn &lt;- function(dictionary, schema, wave12) {
  issues &lt;- s3_diagnosis_validate_fn(dictionary, schema, wave12)
  if (nrow(issues)) stop("S4 dictionary validation failed: ", paste(capture.output(print(issues)), collapse = "\n"))
  stopifnot(!anyDuplicated(dictionary$var), all(grepl("^V[0-9]+$", dictionary$var)))
  rules &lt;- purrr::map_dfr(c("wave1", "wave2", "wave3A", "wave3B"), function(wave) {
    source_expressions &lt;- dictionary[[paste0(wave, "_colname")]]
    tibble::tibble(wave = wave, var = dictionary$var, filename = dictionary$filename,
                   expression = source_expressions)
  })
  rules$terms &lt;- lapply(rules$expression, function(x) {
    if (is.na(x)) character() else strsplit(x, " + ", fixed = TRUE)[[1L]]
  })
  if (any(vapply(rules$terms, function(x) any(!nzchar(x)), logical(1)))) stop("Empty source term")
  rules
}
s4a_diagnosis_expression_fn &lt;- function(terms, wave) {
  if (!length(terms)) return("CAST(NULL AS DOUBLE)")
  quoted &lt;- s4a_diagnosis_identifier_fn(terms)
  if (length(terms) == 1L) return(quoted)
  parts &lt;- if (wave %in% c("wave1", "wave2")) {
    paste0("CASE WHEN ", quoted, " = -1 THEN 0 ELSE ", quoted, " END")
  } else paste0("coalesce(", quoted, ", 0)")
  paste(parts, collapse = " + ")
}
s4a_diagnosis_evaluation_rules_df &lt;- s4a_diagnosis_rules_fn(
  s3_diagnosis_dictionary_df, s3_w3_column_dictionary_df,
  dplyr::bind_rows(
    dplyr::select(s3_diagnosis_wave12_dictionary_df, Column.Name),
    dplyr::select(s3_diagnosis_supplementary_dictionary_df, Column.Name)
  )
)
s4a_diagnosis_wave12_expected_columns_df &lt;- s4a_diagnosis_evaluation_rules_df |&gt;
  dplyr::filter(wave %in% c("wave1", "wave2")) |&gt;
  dplyr::select(wave, terms) |&gt; tidyr::unnest_longer(terms) |&gt; dplyr::distinct()
s4a_diagnosis_output_groups_chr &lt;- unique(stats::na.omit(s3_diagnosis_dictionary_df$filename))








