Tip Procedure: Inventory Stagecoach Sources And Describe Each File



The execution page refreshes the list of staged CSV paths before each build. Individual file targets detect content changes. The source snapshot below records the hashes captured by ingestion as derived provenance; it is never read back as configuration or as an input-discovery prerequisite.
s8_new_wave_sources_fn &lt;- function(roots) {
  x &lt;- s8_new_wave_inventory_fn(roots, hash = FALSE)
  x &lt;- x[x$extension == "csv", c("source_id", "relative_path", "path")]
  if (!nrow(x)) stop("No new-wave CSVs are staged through Stagecoach.")
  if (anyDuplicated(x[c("source_id", "relative_path")])) stop("Repeated staged CSV paths.")
  x$source_file &lt;- paste(x$source_id, x$relative_path, sep = "/")
  x
}
s8_new_wave_snapshot_fn &lt;- function(paths, inventory) {
  hashes &lt;- dplyr::bind_rows(lapply(paths, function(path) {
    duckplyr::read_parquet_duckdb(path, prudence = "stingy") |&gt;
      dplyr::distinct(`_source_id`, `_source_file`, `_source_md5`) |&gt;
      dplyr::collect() |&gt;
      dplyr::rename(source_id = `_source_id`, source_file = `_source_file`, content_md5 = `_source_md5`)
  }))
  stopifnot(nrow(hashes) == nrow(inventory), !anyDuplicated(hashes[c("source_id", "source_file")]))
  snapshot &lt;- dplyr::left_join(dplyr::select(inventory, source_id, relative_path, source_file), hashes,
    by = c("source_id", "source_file"), relationship = "one-to-one")
  stopifnot(!anyNA(snapshot$content_md5))
  snapshot
}
s8_new_wave_table_key_fn &lt;- function(path) {
  parts &lt;- strsplit(tolower(path), "/", fixed = TRUE)[[1L]]
  table &lt;- which(grepl("^tableau ", parts))
  key &lt;- paste(parts[seq.int(if (length(table)) tail(table, 1L) else length(parts), length(parts))], collapse = "/")
  key &lt;- gsub("janv\\s*-\\s*juin|juillet\\s*-\\s*dec|\\b[0-9]{6}\\b|\\b20[0-9]{2}\\b", " ", key, perl = TRUE)
  trimws(gsub(" +", " ", gsub(" .csv", ".csv", key, fixed = TRUE)))
}
s8_new_wave_schema_fn &lt;- function(paths) {
  dplyr::bind_rows(lapply(paths, function(path) {
    relation &lt;- duckplyr::read_parquet_duckdb(path, prudence = "stingy")
    info &lt;- relation |&gt; dplyr::distinct(`_source_id`, `_source_file`) |&gt; dplyr::collect()
    stopifnot(nrow(info) == 1L)
    periods &lt;- relation |&gt; dplyr::distinct(periodcode) |&gt; dplyr::collect()
    cols &lt;- setdiff(names(relation), c("_source_id", "_source_file", "_source_row", "_source_md5"))
    tibble::tibble(source_id = info$`_source_id`, source_file = info$`_source_file`,
      table_key = s8_new_wave_table_key_fn(info$`_source_file`), position = seq_along(cols),
      source_name = cols, is_metadata = cols %in% s8_new_wave_metadata_fn(),
      periods = rep(list(sort(unique(periods$periodcode))), length(cols)))
  }))
}
s8_new_wave_schema_df &lt;- s8_new_wave_schema_fn(s8_new_wave_raw_parquet)
s8_new_wave_source_snapshot_df &lt;- s8_new_wave_snapshot_fn(s8_new_wave_raw_parquet, s8_new_wave_source_inventory_df)








